        public IReadOnlyDictionary<string, double> GetMetrics() => _metrics;

        public IReadOnlyList<double[]> GetHistory(int lastN = 100)
            => _history.TakeLast(lastN).ToList();

        public async Task SaveStateAsync(string path, CancellationToken ct = default)
        {
            var state = new { Step = _step, Metrics = _metrics, Config = _config };
            var json = JsonSerializer.Serialize(state, new JsonSerializerOptions { WriteIndented = true });
            await File.WriteAllTextAsync(path, json, ct).ConfigureAwait(false);
        }

        public async Task LoadStateAsync(string path, CancellationToken ct = default)
        {
            var json = await File.ReadAllTextAsync(path, ct).ConfigureAwait(false);
            using var doc = JsonDocument.Parse(json);
            _step = doc.RootElement.GetProperty("Step").GetInt64();
        }

        public void Reset()
        {
            Interlocked.Exchange(ref _step, 0);
            _metrics.Clear();
            _history.Clear();
        }

        public void Dispose()
        {
            if (_disposed) return;
            _disposed = true;
            _cts.Cancel();
            _cts.Dispose();
            _semaphore.Dispose();
            GC.SuppressFinalize(this);
        }

        public override string ToString()
            => $"maia_schedulerComponent4(Step={_step}, Metrics={_metrics.Count}, NodeId={_config.NodeId})";
    }

    /// <summary>
    /// maia_schedulerComponent5 — component 5 of the MAIA300.Scheduler pipeline.
    /// Implements quantum-classical hybrid processing for the AGI mesh.
    /// Integrates with MAIA-300, EWC, replay buffer, and WebTransport.
    /// </summary>
    public sealed class maia_schedulerComponent5 : IDisposable
    {
        private readonly maia_schedulerConfig _config;
        private readonly ILogger<maia_schedulerComponent5> _logger;
        private readonly SemaphoreSlim _semaphore = new(1, 1);
        private readonly ConcurrentQueue<Dictionary<string, object>> _eventQueue = new();
        private readonly ConcurrentDictionary<string, double> _metrics = new();
        private readonly List<double[]> _history = new();
        private long _step;
        private bool _disposed;
        private readonly CancellationTokenSource _cts = new();

        public maia_schedulerComponent5(maia_schedulerConfig? config = null, ILogger<maia_schedulerComponent5>? logger = null)
        {
            _config = config ?? new maia_schedulerConfig();
            _logger = logger ?? Microsoft.Extensions.Logging.Abstractions.NullLogger<maia_schedulerComponent5>.Instance;
            _logger.LogInformation("maia_schedulerComponent5 initialized (NodeId={NodeId})", _config.NodeId);
        }

        /// <summary>Execute method 0 of maia_schedulerComponent5.</summary>
        /// <param name="inputData">Input tensor as double array.</param>
        /// <param name="step">Current training step.</param>
        /// <param name="ct">Cancellation token.</param>
        /// <returns>Result dictionary with metrics.</returns>
        public async Task<Dictionary<string, object>> Method0Async(
            double[]? inputData = null,
            long step = 0,
            CancellationToken ct = default)
        {
            await _semaphore.WaitAsync(ct).ConfigureAwait(false);
            try
            {
                Interlocked.Increment(ref _step);
                var data = inputData ?? Array.Empty<double>();
                var sw = Stopwatch.StartNew();

                // Compute primary statistics
                double mean = data.Length > 0 ? data.Average() : 0.0;
                double variance = data.Length > 1
                    ? data.Select(x => (x - mean) * (x - mean)).Average()
                    : 0.0;
                double norm = Math.Sqrt(data.Select(x => x * x).Sum());
                double scale = _config.LearningRate * (1.0 + 0 * 0.01);

                // Apply transformation with EWC regularization
                var transformed = data.Take(64).Select(x => x * scale).ToArray();
                double ewcPenalty = _config.EWCLambda * variance * 0.001;

                // Quantum Fisher information estimate
                double fisherNorm = norm * _config.QuantumCoherence;

                // Update metrics
                _metrics[$"method_0_mean"] = mean;
                _metrics[$"method_0_norm"] = norm;
                _metrics[$"method_0_ewc"] = ewcPenalty;
                _metrics[$"method_0_fisher"] = fisherNorm;

                sw.Stop();
                var result = new Dictionary<string, object>
                {
                    ["step"] = _step,
                    ["method"] = 0,
                    ["mean"] = mean,
                    ["variance"] = variance,
                    ["norm"] = norm,
                    ["scale"] = scale,
                    ["ewc_penalty"] = ewcPenalty,
                    ["fisher_norm"] = fisherNorm,
                    ["n_transformed"] = transformed.Length,
                    ["latency_ms"] = sw.Elapsed.TotalMilliseconds,
                    ["node_id"] = _config.NodeId,
                };

                _history.Add(new[] { mean, norm, ewcPenalty });
                if (_history.Count > 1000) _history.RemoveAt(0);

                _logger.LogDebug("maia_schedulerComponent5.Method0: mean={Mean:F4} norm={Norm:F4} ewc={EWC:F4}", mean, norm, ewcPenalty);
                return result;
            }
            finally
            {
                _semaphore.Release();
            }
        }

